<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { request } from '../../services/request.js'

const loading=ref(true), savingRole=ref(''), savingNewRole=ref(false), savingAccount=ref(false), savingPassword=ref(false), showRoleCreate=ref(false), showAccountCreate=ref(false), error=ref(''), passwordMessage=ref('')
const menus=ref([]), roles=ref([]), accounts=ref([]), selectedRoleId=ref('')
const accountForm=reactive({username:'',password:'',roleId:''})
const roleForm=reactive({name:'',description:'',menuCodes:[]})
const passwordForm=reactive({accountId:'',username:'',password:'',confirmation:''})
const selectedRole=computed(()=>roles.value.find(item=>item.id===selectedRoleId.value)||roles.value[0]||null)
const selectedCodes=computed(()=>new Set(selectedRole.value?.menuCodes||[]))
async function load(){loading.value=true;error.value='';try{const data=await request('/admin/roles');menus.value=data.menus||[];roles.value=data.roles||[];accounts.value=data.accounts||[];if(!roles.value.some(item=>item.id===selectedRoleId.value))selectedRoleId.value=roles.value[0]?.id||'';if(!accountForm.roleId)accountForm.roleId=roles.value.find(item=>item.code==='ADMIN')?.id||roles.value[0]?.id||''}catch(e){error.value=e.message||'角色配置加载失败'}finally{loading.value=false}}
function checked(code){return selectedCodes.value.has(code)}
function toggle(code){if(!selectedRole.value||selectedRole.value.systemRole)return;const next=new Set(selectedCodes.value);next.has(code)?next.delete(code):next.add(code);selectedRole.value.menuCodes=[...next]}
function openRoleCreate(){error.value='';roleForm.name='';roleForm.description='';roleForm.menuCodes=[];showRoleCreate.value=true}
function closeRoleCreate(){if(!savingNewRole.value)showRoleCreate.value=false}
function roleMenuChecked(code){return roleForm.menuCodes.includes(code)}
function toggleRoleMenu(code){roleForm.menuCodes=roleMenuChecked(code)?roleForm.menuCodes.filter(item=>item!==code):[...roleForm.menuCodes,code]}
async function createRole(){savingNewRole.value=true;error.value='';try{const data=await request('/admin/roles',{method:'POST',body:JSON.stringify(roleForm)});menus.value=data.menus||menus.value;roles.value=data.roles||roles.value;accounts.value=data.accounts||accounts.value;selectedRoleId.value=data.createdRoleId||roles.value.find(item=>item.name===roleForm.name)?.id||selectedRoleId.value;showRoleCreate.value=false;passwordMessage.value=`已创建角色 ${roleForm.name}。`;}catch(e){error.value=e.message||'角色创建失败'}finally{savingNewRole.value=false}}
async function saveMenus(){if(!selectedRole.value||selectedRole.value.systemRole)return;savingRole.value=selectedRole.value.id;try{const data=await request(`/admin/roles/${encodeURIComponent(selectedRole.value.id)}/menus`,{method:'PUT',body:JSON.stringify({menuCodes:selectedRole.value.menuCodes})});menus.value=data.menus||menus.value;roles.value=data.roles||roles.value;accounts.value=data.accounts||accounts.value}catch(e){error.value=e.message||'菜单权限保存失败'}finally{savingRole.value=''}}
function openAccountCreate(){error.value='';accountForm.username='';accountForm.password='';accountForm.roleId=roles.value.find(item=>item.code==='ADMIN')?.id||roles.value[0]?.id||'';showAccountCreate.value=true}
function closeAccountCreate(){if(!savingAccount.value)showAccountCreate.value=false}
async function createAccount(){savingAccount.value=true;error.value='';try{const data=await request('/admin/accounts',{method:'POST',body:JSON.stringify(accountForm)});menus.value=data.menus||menus.value;roles.value=data.roles||roles.value;accounts.value=data.accounts||accounts.value;showAccountCreate.value=false;passwordMessage.value=`已创建账号 ${accountForm.username}，请通过安全渠道交付初始密码。`;accountForm.username='';accountForm.password=''}catch(e){error.value=e.message||'账号创建失败'}finally{savingAccount.value=false}}
function openPassword(account){passwordMessage.value='';passwordForm.accountId=account.id;passwordForm.username=account.username;passwordForm.password='';passwordForm.confirmation=''}
function closePassword(force=false){if(savingPassword.value&&!force)return;passwordForm.accountId='';passwordForm.username='';passwordForm.password='';passwordForm.confirmation=''}
async function resetPassword(){if(passwordForm.password!==passwordForm.confirmation){error.value='两次输入的密码不一致';return}savingPassword.value=true;error.value='';try{const username=passwordForm.username;const data=await request(`/admin/accounts/${encodeURIComponent(passwordForm.accountId)}/password`,{method:'PUT',body:JSON.stringify({password:passwordForm.password})});menus.value=data.menus||menus.value;roles.value=data.roles||roles.value;accounts.value=data.accounts||accounts.value;const currentRevoked=Boolean(data.currentSessionRevoked);closePassword(true);passwordMessage.value=currentRevoked?'当前账号密码已修改，请使用新密码重新登录。':`已修改 ${username} 的密码，原有登录会话已失效。`;if(currentRevoked)window.dispatchEvent(new CustomEvent('admin-unauthorized'))}catch(e){error.value=e.message||'密码修改失败'}finally{savingPassword.value=false}}
onMounted(load)
</script>

<template>
  <section>
    <div class="page-heading"><div><h1>角色与权限</h1><p>管理端按登录账号所属角色显示菜单，并在后端接口层再次校验权限。</p></div><button class="refresh" :disabled="loading" @click="load">刷新</button></div>
    <div v-if="loading" class="panel state">正在读取角色配置…</div><div v-else-if="error && !roles.length" class="panel state error">{{ error }}</div>
    <template v-else>
      <div v-if="error" class="error-line">{{ error }}</div>
      <div class="layout">
        <section class="panel role-panel"><div class="role-heading"><h2>角色</h2><button class="mini-primary" @click="openRoleCreate">新增角色</button></div><button v-for="role in roles" :key="role.id" :class="['role-row',{active:role.id===selectedRole?.id}]" @click="selectedRoleId=role.id"><span><strong>{{ role.name }}</strong><small>{{ role.description }}</small></span><b>{{ role.menuCodes?.length || 0 }} 项</b></button></section>
        <section class="panel permission-panel"><template v-if="selectedRole"><div class="panel-title"><div><h2>{{ selectedRole.name }}的菜单权限</h2><p>{{ selectedRole.systemRole ? '超级管理员始终拥有全部菜单权限。' : '勾选后保存，新的会话和后续请求将按新菜单权限执行。' }}</p></div><button v-if="!selectedRole.systemRole" class="primary" :disabled="savingRole===selectedRole.id" @click="saveMenus">{{ savingRole===selectedRole.id?'保存中…':'保存菜单权限' }}</button></div><div class="menu-grid"><label v-for="menu in menus" :key="menu.code" :class="{locked:selectedRole.systemRole}"><input type="checkbox" :checked="checked(menu.code)" :disabled="selectedRole.systemRole" @change="toggle(menu.code)"/><span>{{ menu.icon }} {{ menu.name }}</span><small>{{ menu.path }}</small></label></div></template></section>
      </div>
      <section class="panel account-panel"><div class="account-heading"><div><h2>管理端账号</h2><p>密码仅保存为 PBKDF2 哈希；可在此重置密码，重置后该账号原有登录会话会立即失效。</p></div><button class="primary" @click="openAccountCreate">创建账号</button></div><p v-if="passwordMessage" class="success-line">{{ passwordMessage }}</p><table><thead><tr><th>账号</th><th>角色</th><th>状态</th><th>最近登录</th><th>操作</th></tr></thead><tbody><tr v-for="account in accounts" :key="account.id"><td>{{ account.username }}</td><td>{{ account.roleName }}</td><td><span class="tag">{{ account.enabled ? '启用' : '停用' }}</span></td><td>{{ account.lastLoginAt ? new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'medium',timeStyle:'short',hour12:false}).format(new Date(account.lastLoginAt)) : '从未登录' }}</td><td><button class="link-button" @click="openPassword(account)">修改密码</button></td></tr></tbody></table></section>
      <div v-if="showRoleCreate" class="password-mask" @click.self="closeRoleCreate"><form class="password-dialog role-dialog" @submit.prevent="createRole"><h2>新增角色</h2><p>创建后可继续在角色列表中调整权限，并可分配给新的管理账号。</p><label>角色名称</label><input v-model.trim="roleForm.name" required maxlength="80" placeholder="例如：内容审核员"/><label>角色说明</label><input v-model.trim="roleForm.description" maxlength="255" placeholder="说明该角色的职责范围（可选）"/><label>初始菜单权限</label><div class="role-menu-grid"><label v-for="menu in menus" :key="menu.code"><input type="checkbox" :checked="roleMenuChecked(menu.code)" @change="toggleRoleMenu(menu.code)"/><span>{{ menu.icon }} {{ menu.name }}</span></label></div><div><button type="button" class="cancel-button" :disabled="savingNewRole" @click="closeRoleCreate">取消</button><button class="primary" :disabled="savingNewRole">{{ savingNewRole?'创建中…':'确认创建' }}</button></div></form></div>
      <div v-if="showAccountCreate" class="password-mask" @click.self="closeAccountCreate"><form class="password-dialog" @submit.prevent="createAccount"><h2>创建管理账号</h2><p>创建后请通过安全渠道交付初始密码。账号创建完成即可按所选角色登录。</p><label>账号</label><input v-model.trim="accountForm.username" required maxlength="40" pattern="[A-Za-z][A-Za-z0-9_.-]{2,39}" autocomplete="username" placeholder="例如 editor01"/><label>初始密码</label><input v-model="accountForm.password" required type="password" minlength="10" maxlength="128" autocomplete="new-password" placeholder="至少 10 位密码"/><label>角色</label><select v-model="accountForm.roleId" required><option v-for="role in roles" :key="role.id" :value="role.id">{{ role.name }}</option></select><div><button type="button" class="cancel-button" :disabled="savingAccount" @click="closeAccountCreate">取消</button><button class="primary" :disabled="savingAccount">{{ savingAccount?'创建中…':'确认创建' }}</button></div></form></div>
      <div v-if="passwordForm.accountId" class="password-mask" @click.self="closePassword"><form class="password-dialog" @submit.prevent="resetPassword"><h2>修改密码</h2><p>正在修改 <strong>{{ passwordForm.username }}</strong> 的密码。保存后该账号的所有登录会话会失效。</p><label>新密码</label><input v-model="passwordForm.password" required type="password" minlength="10" maxlength="128" autocomplete="new-password" placeholder="10–128 位密码"/><label>确认新密码</label><input v-model="passwordForm.confirmation" required type="password" minlength="10" maxlength="128" autocomplete="new-password" placeholder="再次输入新密码"/><div><button type="button" class="cancel-button" :disabled="savingPassword" @click="closePassword">取消</button><button class="primary" :disabled="savingPassword">{{ savingPassword?'保存中…':'确认修改' }}</button></div></form></div>
    </template>
  </section>
</template>

<style scoped>
.refresh,.primary,.cancel-button,.mini-primary{height:39px;padding:0 16px;border-radius:8px;font-weight:650}.refresh,.cancel-button{border:1px solid #cddcf1;color:#126ff4;background:#fff}.primary,.mini-primary{border:0;color:#fff;background:#126ff4}.mini-primary{height:31px;padding:0 10px;font-size:12px}.state{margin-top:24px;padding:58px;text-align:center;color:#78859b}.error{color:#bd4050}.error-line,.success-line{margin-top:18px;padding:12px;border-radius:9px}.error-line{color:#a33e48;background:#fff0f1}.success-line{color:#087a58;background:#e9f8f1}.layout{display:grid;grid-template-columns:320px 1fr;gap:18px;margin-top:24px}.role-panel,.permission-panel,.account-panel{padding:22px}.role-panel h2,.permission-panel h2,.account-panel h2{margin:0;font-size:18px}.role-heading{display:flex;align-items:center;justify-content:space-between;gap:10px}.role-row{display:flex;width:100%;align-items:center;justify-content:space-between;gap:12px;margin-top:12px;padding:14px;border:1px solid #e1e8f2;border-radius:10px;color:#243451;background:#fff;text-align:left}.role-row.active{border-color:#78b0fb;background:#f2f7ff}.role-row strong,.role-row small{display:block}.role-row small,.panel-title p,.account-panel p{margin-top:5px;color:#79859b;font-size:12px;line-height:1.5}.role-row b{color:#1674ef;font-size:12px}.panel-title,.account-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.panel-title p{margin-bottom:0}.menu-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:20px}.menu-grid label{display:grid;grid-template-columns:auto 1fr;gap:5px 9px;align-items:center;padding:12px;border:1px solid #e1e8f2;border-radius:9px;color:#33425e;font-size:13px}.menu-grid small{grid-column:2;color:#8692a7;font-size:11px}.menu-grid label.locked{opacity:.72}.account-panel{margin-top:18px}.account-panel input,.account-panel select,.password-dialog input,.password-dialog select{height:40px;padding:0 11px;border:1px solid #d6dfeb;border-radius:8px;background:#fff}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}th{color:#738099;font-size:12px}.tag{padding:4px 8px;border-radius:99px;color:#0a805b;background:#e8f8f1;font-size:12px}.link-button{border:0;padding:0;color:#126ff4;background:transparent;font-weight:650}.password-mask{position:fixed;inset:0;z-index:30;display:grid;place-items:center;padding:20px;background:rgba(24,38,65,.48)}.password-dialog{width:min(100%,440px);display:grid;gap:10px;padding:26px;border-radius:14px;background:#fff;box-shadow:0 18px 50px rgba(24,38,65,.24)}.role-dialog{width:min(100%,620px)}.password-dialog h2,.password-dialog p{margin:0}.password-dialog p{color:#718098;font-size:13px;line-height:1.55}.password-dialog label{margin-top:4px;color:#33425e;font-size:13px;font-weight:650}.password-dialog div{display:flex;justify-content:flex-end;gap:10px;margin-top:12px}.role-menu-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;max-height:260px;overflow:auto;padding:4px}.role-menu-grid label{display:flex;align-items:center;gap:7px;margin:0!important;padding:9px;border:1px solid #e1e8f2;border-radius:8px;font-weight:500}.role-menu-grid input{width:auto;height:auto;padding:0}@media(max-width:1000px){.layout{grid-template-columns:1fr}.menu-grid,.role-menu-grid{grid-template-columns:1fr}}
</style>
